# Issuance couples identity to attestation state
def issue_cert(node):
    quote = node.get_attestation_quote()          # signed PCR/measurement
    if not verify_measurement(quote, policy.golden(node.role)):
        raise Deny('attestation mismatch')        # unknown firmware -> no cert
    csr = node.make_csr()
    return ca.sign(csr, ttl_hours=8, spiffe_id=node.workload_id)

# Load path: verify then decrypt (authenticated encryption, e.g. AES-GCM)
def load_bitstream(blob):
    hdr, ct, tag = parse(blob)
    if not aead_verify(ct, tag, key=device_key, aad=hdr):
        halt('bitstream auth failed')     # refuse before decrypt
    plain = aead_decrypt(ct, key=device_key)
    if hdr.design_id not in policy.allowed_designs:
        halt('unexpected design id')
    configure_fabric(plain)

# Verifier dispatches by declared algorithm and enforces a floor
def verify(artifact):
    alg = artifact.alg_id
    if alg not in policy.allowed or policy.strength(alg) < policy.floor:
        return REJECT               # deprecated schemes fail policy, not code
    return REGISTRY[alg].verify(artifact)

# Enforced two-person authorization for consequential actions
def authorize(action, approvals):
    roles = {a.role for a in approvals if a.valid()}
    need  = policy.required_roles(action.kind)   # e.g. {'operator','physics'}
    if not need.issubset(roles):
        return DENY('missing distinct roles')
    if len({a.identity for a in approvals}) < 2:  # must be two people
        return DENY('single individual')
    if action.expired():
        return DENY('window closed')
    audit(action, approvals)                       # both identities logged
    return ALLOW

# Reject a channel that violates cross-diagnostic physics consistency
def diagnostic_ok(fused):
    # e.g. line-integrated density vs Thomson profile vs stored energy
    resid = physics_residual(fused)             # should be ~0 for real data
    if resid > policy.tolerance:
        flag_spoof_suspect(fused.channels)
        return False
    if disagreement(fused.redundant) > policy.redundant_tol:
        return False
    return True

# Score a flow against the learned baseline; escalate on high anomaly
def monitor(flow, mode):
    s = baseline.score(flow, context=mode)      # 0..1, higher = stranger
    if s > policy.alert_threshold:
        alert(flow, s)
        record(flow, s)                         # into the audit log
    if s > policy.contain_threshold:
        propose_isolation(flow.src_id)          # human-confirmed, fail-safe
